				return false;

			if (!SessionLeaveDefaultCheck(state))
				return false;

			if (IsAllNetworkAsyncCompleted())
				return SessionLeaveAsyncCore(state);

			isSessionLeaveRequest = true;
			sessionLeaveRequestState = state;
			SystemCallBackFinal();
			return true;
		}
		private static bool SessionLeaveDefaultCheck(global::INL1.IlcaNetSessionState state) {
			if (EmergencyCheck())
				return false;

			if (isNetworkFinalRequest)
				return false;

			if (isErrorHandleMoving)
				return false;

			if (state != IlcaNetSessionState.SS_MatchingWait && state != IlcaNetSessionState.SS_GamingLeave)
				return false;

			IlcaNetSessionState nowState = SessionStateNow();
			if (nowState != IlcaNetSessionState.SS_GamingFront && nowState != IlcaNetSessionState.SS_Gaming &&
				nowState != IlcaNetSessionState.SS_GamingLeave && nowState != IlcaNetSessionState.SS_GamingError)
				return false;

			GameState gameState = GameStateNow();
			bool isGame = gameState == GameState.GS_GameFront || gameState == GameState.GS_Game ||
				gameState == GameState.GS_GameLeave || gameState == GameState.GS_GameError;
			if (state != IlcaNetSessionState.SS_GamingLeave)
				return isGame;

			if (!isGame)
				return false;

			if (nowState == IlcaNetSessionState.SS_GamingLeave)
				return false;

			if (gameState == GameState.GS_GameLeave)
				return false;

			if (!checkSessionStateNowOnStageInConnected)
			{
				isSessionLeaveRequest = false;
				return false;
			}
			return true;
		}
		private static bool SessionLeaveAsyncCore(global::INL1.IlcaNetSessionState state) {
			PiaPlugin.Result result = default;
			if (state == IlcaNetSessionState.SS_MatchingWait)
			{
				SystemCallBackFinal();
				return CleanupRecoveryToLoggedIn();
			}
			if (state != IlcaNetSessionState.SS_GamingLeave)
				return false;

			result = PiaPlugin.ChangeStateAsync(PiaPlugin.State.SessionCleanedUp);
			if (result.IsFailure())
			{
				result.Trace();
				return false;
			}
			SystemCallBackFinal();
			GameStateChangeSet(GameState.GS_AsyncWait, PiaPlugin.AsyncProcessId.ChangeState, GameState.GS_GameLeave);
			return true;
		}
		private static bool NetGamerNameGet(global::PiaPluginSession.SessionEvent ev, ref string gamerName, ref byte nameStringLanguage) {
			uint nameBytes = 0;
			IlcaNetNative.INLpiaSessionGetPlayerInfo(ev.constantId, gamerNameConvBuff, ref nameStringLanguage, ref nameBytes);
			if (nameBytes < 2)
			{
				gamerName = "";
			}
			else
			{
				byte[] name = new byte[nameBytes - 1];
				for (int i = 0; i < nameBytes - 1; i++)
					name[i] = gamerNameConvBuff[i];

				gamerName = System.Text.Encoding.UTF8.GetString(name);
			}
			return true;
		}
