		private static bool EmergencyCheckFromFamilyClass() {
			if (!EmergencyCheck())
				return false;

			if (SessionFinalizeProcessMovingCheck())
			{
				EmergencyInit();
				return false;
			}
			if (!IsAllNetworkAsyncCompleted())
				return false;

			EmergencyInit();
			HandleError(lastEmergencyResult);
			return true;
		}
		private static bool NetworkFinalRequestCheck() {
			if (!isNetworkFinalRequest)
				return false;

			if (SessionFinalizeProcessMovingCheck())
			{
				isNetworkFinalRequest = false;
				return false;
			}
			if (!IsAllNetworkAsyncCompleted())
				return false;

			NetworkFinalAsync();
			isNetworkFinalRequest = false;
			return true;
		}
		private static bool SessionLeaveRequestCheck() {
			if (!isSessionLeaveRequest)
				return false;

			if (!IsAllNetworkAsyncCompleted())
				return false;

			if (SessionFinalizeProcessMovingCheck())
			{
				isSessionLeaveRequest = false;
				return false;
			}
			if (!SessionLeaveDefaultCheck(sessionLeaveRequestState))
				return false;

			if (!SessionLeaveAsyncCore(sessionLeaveRequestState))
				return false;

			isSessionLeaveRequest = false;
			return true;
		}
		private static void SessionStatusCheckForFamilyClass() {
			if (!isPlatformLibraryFullInitialized || SessionFinalizeProcessMovingCheck())
			{
				nowStationNumber = 0;
				checkSessionStateNowOnStageInConnected = false;
				return;
			}
			if (IlcaNetNative.INLpiaSessionGetStatus() != 1)
			{
				checkSessionStateNowOnStageInConnected = false;
				nowStationNumber = 0;
				return;
			}
			checkSessionStateNowOnStageInConnected = true;
			int num = NumStation();
			if (num < 0)
				nowStationNumber = 0;
			else
				nowStationNumber = (uint)num;
		}
		private static global::INL1.IlcaNetSessionState UpdateCore() {
			if (SuspendFinishCheck(true))
			{
				EmergencyCheckFromFamilyClass();
				NetworkFinalRequestCheck();
				SessionLeaveRequestCheck();
				UpdateDispatchCore(true);
				if (GameStateNow() == GameState.GS_AsyncWait)
				{
					SessionStateSet(IlcaNetSessionState.SS_WorkingAsync);
					GameState_AsyncWaitCore();
					if (GameStateNow() != GameState.GS_AsyncWait)
						UpdateSwitchCore();
				}
				else
				{
					UpdateSwitchCore();
				}
			}
			return SessionStateNow();
		}
		private static void UpdateDispatchWorkerTh() {
			PiaPlugin.Result dispatchResult = default;
			PiaPlugin.AsyncState asyncState = default;
			updateDispatchWorkerdispatchResultFlag = false;
			updateDispatchWorkerAsyncResultFlag = false;
			do
			{
				System.Threading.Thread.Sleep(WorkerThreadSleepTime);
				PiaPlugin.Dispatch();
				dispatchResult = PiaPlugin.CheckDispatchError();
				if (dispatchResult.IsFailure() && !updateDispatchWorkerdispatchResultFlag)
				{
					updateDispatchWorkerdispatchResult = dispatchResult;
					updateDispatchWorkerdispatchResultFlag = true;
				}
				asyncState = PiaPlugin.GetAsyncProcessState(updateDispatchWorkerAsyncProcessId);
			}
			while (!asyncState.isCompleted);

			if (asyncState.result.IsFailure())
			{
				updateDispatchWorkerAsyncResult = asyncState.result;
				updateDispatchWorkerAsyncResultFlag = true;
			}
			IlcaNetServer.MainThreadDispatchControl(true);
		}
		private static bool UpdateDispatchWorkerSet(global::PiaPlugin.AsyncProcessId apid, bool PriorityMode2 = false) {
			isMainThreadDispatchActive = false;
			updateDispatchWorkerAsyncProcessId = apid;
			System.Threading.Thread thread = new System.Threading.Thread(new System.Threading.ThreadStart(UpdateDispatchWorkerTh));
			thread.IsBackground = true;
			thread.Priority = PriorityMode2 ? System.Threading.ThreadPriority.Highest : System.Threading.ThreadPriority.BelowNormal;
			thread.Start();
			return true;
		}
		private static void UpdateDispatchWorkerThSuspend() {
			PiaPlugin.Result result = default;
			updateDispatchWorkerdispatchResultFlagSuspend = false;
			List<PiaPluginSession.SessionEvent> sessionEventList = new List<PiaPluginSession.SessionEvent>();
			while (true)
			{
				System.Threading.Thread.Sleep(WorkerThreadSleepTime);
				if (!updateDispatchWorkerdispatchSuspendGoing)
					break;

				sessionEventList.Clear();
				if (!updateDispatchWorkerdispatchResultFlagSuspend)
				{
					PiaPlugin.Dispatch();
					sessionEventList = PiaPlugin.GetSessionEventList();
					DispatchAftre(true, sessionEventList);
				}
				result = PiaPlugin.CheckDispatchError();
				if (result.IsFailure() && !updateDispatchWorkerdispatchResultFlagSuspend)
				{
					updateDispatchWorkerdispatchResultSuspend = result;
					updateDispatchWorkerdispatchResultFlagSuspend = true;
				}
				if (!updateDispatchWorkerdispatchResultFlagSuspend)
					sessionEventListSuspendDispatch.AddRange(sessionEventList);
			}
			updateDispatchWorkerdispatchSuspendFinish = true;
		}
		private static bool UpdateDispatchWorkerSetSuspend() {
			System.Threading.Thread thread = new System.Threading.Thread(new System.Threading.ThreadStart(UpdateDispatchWorkerThSuspend));
			thread.IsBackground = true;
			thread.Priority = System.Threading.ThreadPriority.Highest;
			thread.Start();
			return true;
		}
		public static bool SuspendON() {
			if (GameStateNow() == GameState.GS_Game && !updateDispatchWorkerdispatchSuspendGoing)
			{
				IlcaNetServer.MainThreadDispatchControl(false);
				sessionEventListSuspendDispatch.Clear();
				updateDispatchWorkerdispatchSuspendGoing = true;
				updateDispatchWorkerdispatchSuspendFinish = false;
				UpdateDispatchWorkerSetSuspend();
				return true;
			}
			PiaPlugin.Assert(false);
			return false;
		}
		public static bool SuspendOFFRequest() {
			updateDispatchWorkerdispatchSuspendGoing = false;
			return true;
		}
		public static bool SuspendOFF() {
			if (!updateDispatchWorkerdispatchSuspendGoing)
			{
				PiaPlugin.Assert(false);
				return false;
			}
			updateDispatchWorkerdispatchSuspendGoing = false;
			// shipped busy-wait on a volatile flag (`ldrb ; dmb ish` loop @023baccc–023bace8) set by UpdateDispatchWorkerThSuspend
			while (!updateDispatchWorkerdispatchSuspendFinish)
			{
			}
			return true;
		}
		private static bool SuspendFinishCheck(bool first) {
			if (!first)
				return true;

			if (updateDispatchWorkerdispatchSuspendGoing)
				return true;

			if (!updateDispatchWorkerdispatchSuspendFinish)
				return true;

			updateDispatchWorkerdispatchSuspendFinish = false;
			if (updateDispatchWorkerdispatchResultFlagSuspend)
			{
				updateDispatchWorkerdispatchResultSuspend.Trace();
				HandleError(updateDispatchWorkerdispatchResultSuspend);
				return false;
			}
			if (isSystemCallBackReady)
				CallBackExtension(sessionEventListSuspendDispatch, true);

			IlcaNetServer.MainThreadDispatchControl(true);
			return true;
		}
		private static void UpdateDispatchCore(bool first) {
			PiaPlugin.Result result = default;
			if (!isMainThreadDispatchActive)
				return;

			PiaPlugin.Dispatch();
			result = PiaPlugin.CheckDispatchError();
			List<PiaPluginSession.SessionEvent> sessionEventList = PiaPlugin.GetSessionEventList();
			DispatchAftre(first, sessionEventList);
			if (result.IsFailure())
			{
				result.Trace();
				if (!IsAllNetworkAsyncCompleted())
					return;

				if (SessionFinalizeProcessMovingCheck())
					return;

				HandleError(result);
			}
			else if (isSystemCallBackReady)
			{
				CallBackExtension(sessionEventList, first);
			}
		}
		private static void DispatchAftre(bool first, global::System.Collections.Generic.List<global::PiaPluginSession.SessionEvent> sessionEventList) {
			if (first)
				SessionStatusCheckForFamilyClass();

			if (sessionEventList.Count > 0)
			{
				if (!first)
					SessionStatusCheckForFamilyClass();

				SessionToTransportSet(false, sessionEventList);
			}
		}
		private static void SessionToTransportSet(bool first, global::System.Collections.Generic.List<global::PiaPluginSession.SessionEvent> sessionEventList) {
			for (int i = 0; i < sessionEventList.Count; i++)
			{
				switch (sessionEventList[i].eventType)
				{
					case PiaPluginSession.EventType.EventJoin:
						IlcaNetTransport.ValidityConstantIDSet(sessionEventList[i].stationIndex, sessionEventList[i].constantId);
						if (IlcaNetNative.INLpiaSessionGetHostConstantId() == sessionEventList[i].constantId)
							IlcaNetTransport.HostStationSet(sessionEventList[i].stationIndex, sessionEventList[i].constantId);

						if (IlcaNetNative.INLpiaSessionGetThisConstantId() == sessionEventList[i].constantId)
						{
							IlcaNetTransport.ThisStationSet(sessionEventList[i].stationIndex, sessionEventList[i].constantId);
							NetStationBootCheck();
						}
						break;
					case PiaPluginSession.EventType.EventLeave:
						IlcaNetTransport.ValidityConstantIDSet(sessionEventList[i].stationIndex, 0);
						if (IlcaNetTransport.HostStationConstantIDGet() == sessionEventList[i].constantId)
							IlcaNetTransport.HostStationSet(-1, 0);

						if (IlcaNetTransport.ThisStationConstantIDGet() == sessionEventList[i].constantId)
							IlcaNetTransport.ThisStationSet(-1, 0);
						break;
					case PiaPluginSession.EventType.SessionHostChanged:
						IlcaNetTransport.HostStationSet(sessionEventList[i].stationIndex, sessionEventList[i].constantId);
						break;
				}
			}
		}
		private static void NetStationBootCheck() {
			if (IsNetStationInitialized())
				return;

			NetStation.Boot();
			NetStation.ConstantIdSet(IlcaNetTransport.ThisStationConstantIDGet());
			NetStation.StationIndexSet(IlcaNetTransport.ThisStationIndexGet());
		}
		private static void UpdateSwitchCore() {
			switch (GameStateNow())
			{
				case GameState.GS_NexLogOutWait:
				case GameState.GS_NetworkStartedUpNEX:
					SessionStateSet(IlcaNetSessionState.SS_WorkingAsync);
					break;
				case GameState.GS_NexPiaInitialize:
					SessionStateSet(IlcaNetSessionState.SS_WorkingAsync);
					GameState_NexPiaInitialize();
					break;
				case GameState.GS_NetworkStartedUp:
					SessionStateSet(IlcaNetSessionState.SS_WorkingAsync);
					GameState_NetworkStartedUp();
					break;
				case GameState.GS_LoggedIn:
					SessionStateSet(IlcaNetSessionState.SS_WorkingAsync);
					GameState_LoggedIn();
					break;
				case GameState.GS_LoggedInWaitWorker:
					SessionStateSet(IlcaNetSessionState.SS_WorkingAsync);
					GameState_WaitWorker(GSWaitWorkerEnum.To_GS_SessionStartedUp);
					break;
				case GameState.GS_LoggedInReturnStep:
					SessionStateSet(IlcaNetSessionState.SS_WorkingAsync);
					GameState_LoggedInReturnStep();
					break;
				case GameState.GS_LoggedInReturnWaitWorker:
					SessionStateSet(IlcaNetSessionState.SS_WorkingAsync);
					GameState_WaitWorker(GSWaitWorkerEnum.To_GS_LoggedIn);
					break;
				case GameState.GS_SessionStartedUp:
					SessionStateSet(IlcaNetSessionState.SS_WorkingAsync);
					GameState_SessionStartedUp();
					break;
				case GameState.GS_BrowseSession:
					SessionStateSet(IlcaNetSessionState.SS_WorkingAsync);
					GameState_BrowseSession();
					break;
				case GameState.GS_BrowseSessionAfter_LocalRandom:
					SessionStateSet(IlcaNetSessionState.SS_WorkingAsync);
					GameState_BrowseSessionAfter_LocalRandom2();
					break;
				case GameState.GS_BrowseSessionAfter_InternetRandomAikotobaBefore:
					SessionStateSet(IlcaNetSessionState.SS_MatchingBlock);
					break;
				case GameState.GS_BrowseSessionAfter_InternetRandomAikotoba:
					SessionStateSet(IlcaNetSessionState.SS_WorkingAsync);
					GameState_BrowseSessionAfter_InternetRandomAikotoba();
					break;
				case GameState.GS_CreateOrJoinSessionBefore:
					SessionStateSet(IlcaNetSessionState.SS_WorkingAsync);
					GameState_CreateOrJoinSessionBefore();
					break;
				case GameState.GS_CreateOrJoinSession:
					SessionStateSet(IlcaNetSessionState.SS_MatchingWait);
					break;
				case GameState.GS_JoinProcess:
				case GameState.GS_JoinProcessRandom:
				case GameState.GS_JoinProcess_LocalRandom:
					SessionStateSet(IlcaNetSessionState.SS_WorkingAsync);
					GameState_JoinProcessAll();
					break;
				case GameState.GS_GameFrontBefore_LocalRandom:
					SessionStateSet(IlcaNetSessionState.SS_WorkingAsync);
					GameState_GameFrontBefore_LocalRandom();
					break;
				case GameState.GS_GameFront:
					SessionStateSet(IlcaNetSessionState.SS_GamingFront);
					GameState_GameFront();
					break;
				case GameState.GS_Game:
					SessionStateSet(IlcaNetSessionState.SS_Gaming);
					GameState_Game();
					break;
				case GameState.GS_GameLeave:
					SessionStateSet(IlcaNetSessionState.SS_GamingLeave);
					break;
				case GameState.GS_GameError:
					SessionStateSet(IlcaNetSessionState.SS_GamingError);
					break;
				case GameState.GS_HandleErrorWait:
					SessionStateSet(IlcaNetSessionState.SS_WorkingAsync);
					GameState_HandleErrorWait();
					break;
				case GameState.GS_HandleErrorWaitWorker:
					SessionStateSet(IlcaNetSessionState.SS_WorkingAsync);
					GameState_HandleErrorWaitWorker();
					break;
				case GameState.GS_ErrorHandling:
					SessionStateSet(IlcaNetSessionState.SS_WorkingAsync);
					GameState_ErrorHandling(false);
					break;
				case GameState.GS_Logout:
					SessionStateSet(IlcaNetSessionState.SS_WorkingAsync);
					GameState_LogoutCore();
					break;
				case GameState.GS_LogoutWaitWorker:
					SessionStateSet(IlcaNetSessionState.SS_WorkingAsync);
					GameState_LogoutWaitWorker();
					break;
				case GameState.GS_PiaFrameworkFinalize:
					SessionStateSet(IlcaNetSessionState.SS_WorkingAsync);
					GameState_PiaFrameworkFinalize();
					break;
				case GameState.GS_PiaFrameworkFinalizeAfter:
					SessionStateSet(IlcaNetSessionState.SS_WorkingAsync);
					GameState_PiaFrameworkFinalizeCoreAfter();
					break;
				case GameState.GS_Final:
					SessionStateSet(IlcaNetSessionState.SS_Final);
					break;
				case GameState.GS_Crash:
					SessionStateSet(IlcaNetSessionState.SS_Crash);
					break;
				default:
					SessionStateSet(IlcaNetSessionState.SS_NoInit);
					break;
			}
		}
