		private static void CallBackExtension(global::System.Collections.Generic.List<global::PiaPluginSession.SessionEvent> sessionEventList, bool first) {
			if (first && sessionEventCallbackQueueCount > 0 && CallbackEventQueueCheck())
			{
				for (int i = 0; i < sessionEventCallbackQueueCount; i++)
				{
					CallBackExtensionCore(sessionEventCallbackEventQueue[i], i);
					sessionEventCallbackEventQueue[i] = null;
				}
				sessionEventCallbackQueueCount = 0;
			}
			if (sessionEventList.Count < 1)
				return;

			if (first && CallbackEventQueueCheck())
			{
				for (int i = 0; i < sessionEventList.Count; i++)
					CallBackExtensionCore(sessionEventList[i], i);
			}
			else
			{
				CallbackEventQueueCore(in sessionEventList);
			}
		}
		private static bool CallbackEventQueueCheck() {
			if (SessionStateNow() == IlcaNetSessionState.SS_Gaming || SessionStateNow() == IlcaNetSessionState.SS_GamingFront)
				return true;

			return sessionEventCallbackFuncDelayMode == IlcaNetSessionCallbackMode.Smart;
		}
		private static void CallbackEventQueueCore(in global::System.Collections.Generic.List<global::PiaPluginSession.SessionEvent> sessionEventList) {
			if (sessionEventCallbackQueueCount >= sessionEventCallbackQueueSize)
				return;

			if (sessionEventList.Count < 1)
				return;

			int queueTop = sessionEventCallbackQueueCount;
			for (int i = 0; i < sessionEventList.Count; i++)
			{
				if (sessionEventCallbackQueueCount >= sessionEventCallbackQueueSize)
				{
					DangerousEmergencyCall();
					return;
				}
				sessionEventCallbackEventQueue[queueTop + i] = sessionEventList[i];
				sessionEventCallbackQueueCount++;
			}
		}
		private static void CallBackExtensionCore(global::PiaPluginSession.SessionEvent ev, int i, string str = null) {
			switch (ev.eventType)
			{
				case PiaPluginSession.EventType.EventJoin:
					CallBackExtensionCoreEventJoin(ref NetGamer[ev.stationIndex], ev);
					NetGamer[ev.stationIndex].CopyTo(ref NetGamer2[ev.stationIndex]);
					if (isSessionEventCallbackFuncReady)
						sessionEventCallbackfunc((IlcaNetSessionEventCallbackType)ev.eventType, ev.stationIndex);
					break;
				case PiaPluginSession.EventType.EventLeave:
					if (isSessionEventCallbackFuncReady)
						sessionEventCallbackfunc((IlcaNetSessionEventCallbackType)ev.eventType, ev.stationIndex);

					NetGamer[ev.stationIndex].Final();
					NetGamer2[ev.stationIndex].Final();
					break;
				case PiaPluginSession.EventType.SessionHostChanged:
					if (IsHost())
					{
						SessonOpenCloseInit();
						netSessionOpenCloseStatus = (IlcaNetSessionOpenStatus)PiaPluginSession.GetSessionOpenStatus();
					}
					if (isSessionEventCallbackFuncReady)
						sessionEventCallbackfunc((IlcaNetSessionEventCallbackType)ev.eventType, ev.stationIndex);
					break;
			}
		}
		private static void CallBackExtensionCoreEventJoin(ref global::INL1.IlcaNetGamer gamer, global::PiaPluginSession.SessionEvent ev) {
			gamer.Init();
			gamer.ActiveON();
			if (ev.stationIndex == ThisStationIndex())
				gamer.HomeGamerON();
			else
				gamer.HomeGamerOFF();

			NetGamerNameGet(ev, ref gamer.gamerName, ref gamer.nameStringLanguage);
			gamer.StationIndexSet(ev.stationIndex);
			gamer.ConstantIdSet(ev.constantId);
			gamer.TURNenable = IlcaNetNative.INLpiaStationTURNconnectConstantID(ev.constantId);
		}
		private static void CallBackNetGamerLastEventLeave() {
			if (NetStation == null)
				return;

			if (netSetting.lastEventLeave == IlcaNetSessionCallbackLastEventLeave.NoLastCall)
				return;

			if (!isSessionEventCallbackFuncReady)
				return;

			int myIndex = ThisStationIndex();
			if (myIndex >= 0 && myIndex < maxNetGamer && NetGamer[myIndex].IsActive())
			{
				leaveEvent.stationIndex = myIndex;
				CallBackExtensionCore(leaveEvent, myIndex);
			}
			for (int i = 0; i < netSetting.playerNumMax; i++)
			{
				if (NetGamer[i].IsActive())
				{
					leaveEvent.stationIndex = i;
					CallBackExtensionCore(leaveEvent, i);
				}
			}
		}
		private static void GameState_AsyncWaitCore() {
			PiaPlugin.AsyncState asyncState = PiaPlugin.GetAsyncProcessState(netAsyncProcessId);
			if (!asyncState.isCompleted)
				return;

			PiaPlugin.Result result = asyncState.result;
			if (result.IsFailure())
			{
				switch (netAsyncProcessId)
				{
					case PiaPlugin.AsyncProcessId.ChangeState:
						if (netNextGameState == GameState.GS_JoinProcessRandom || netNextGameState == GameState.GS_PiaFrameworkFinalize)
							break;

						HandleError(result);
						return;
					case PiaPlugin.AsyncProcessId.CreateSession:
					case PiaPlugin.AsyncProcessId.JoinSession:
						break;
					case PiaPlugin.AsyncProcessId.BrowseSession:
						if (AutoRetryCheck(result))
						{
							SystemCallBackFinal();
							CleanupRecoveryToLoggedIn();
						}
						else
						{
							HandleError(result);
						}
						return;
					default:
						HandleError(result);
						return;
				}
			}
			GameStateChangeSet(netNextGameState);
		}
		private static void GameState_NexPiaInitialize() {
			PiaPlugin.Result result = PlatformInitialize();
			if (result.IsFailure())
				return;

			result = PiaPlugin.ChangeStateAsync(PiaPlugin.State.NetworkStartedUp);
			if (result.IsFailure())
			{
				HandleError(result);
				return;
			}
			GameStateChangeSet(GameState.GS_AsyncWait, PiaPlugin.AsyncProcessId.ChangeState, GameState.GS_NetworkStartedUp);
		}
		private static void GameState_NetworkStartedUp() {
			IlcaNetServer.NexAssetsAutoLoginControl(false);
			IlcaNetServer.NexAssetsAutoLogoutControl(false);
			if (netSetting.networkType != IlcaNetSessionNetworkType.Internet)
			{
				GameState_NetworkStartedUp_after();
				return;
			}
			GeneraNexInitializeResult result = GeneralNexInitialize(GameState_NetworkStartedUp_NexCallBack);
			if (result == GeneraNexInitializeResult.AsyncStart)
				GameStateChangeSet(GameState.GS_NetworkStartedUpNEX);
			else if (result == GeneraNexInitializeResult.AlreadyInit)
				GameState_NetworkStartedUp_after();
			else
				DangerousEmergencyCall();
		}
		private static void GameState_NetworkStartedUp_NexCallBack(global::NexPlugin.AsyncResult asyncResult) {
			if (asyncResult.IsSuccess())
			{
				GameState_NetworkStartedUp_after();
				return;
			}
			IlcaNetServer.NexErrorHandling(asyncResult);
			DangerousEmergencyCall();
		}
		private static void GameState_NetworkStartedUp_after() {
			PiaPlugin.Result result = default;
			result = PiaPlugin.ChangeStateAsync(PiaPlugin.State.LoggedIn);
