		private static void GameState_WaitWorker(global::INL1.IlcaNetSession.GSWaitWorkerEnum mode) {
			if (!isMainThreadDispatchActive)
				return;

			if (updateDispatchWorkerdispatchResultFlag)
			{
				HandleError(updateDispatchWorkerdispatchResult);
				return;
			}
			if (updateDispatchWorkerAsyncResultFlag)
			{
				HandleError(updateDispatchWorkerAsyncResult);
				return;
			}
			if (mode == GSWaitWorkerEnum.To_GS_LoggedIn)
				GameStateChangeSet(GameState.GS_LoggedIn);
			else
				GameStateChangeSet(GameState.GS_SessionStartedUp);
		}
