		private static void GameState_SessionStartedUp() {
			PiaPlugin.Result result = default;
			isPlatformLibraryFullInitialized = true;
			joinRandomSessionSetting = new PiaPlugin.JoinRandomSessionSetting();
			createSessionSetting = new PiaPluginSession.CreateSessionSetting();
			sessionSearchCriteriaList[0] = new PiaPluginSession.SessionSearchCriteria();
			if (netSetting.matchingMode == IlcaNetSessionInitMode.MatchingWaitNoSearch)
			{
				GameStateChangeSet(GameState.GS_CreateOrJoinSession);
				return;
			}
			if (netSetting.networkType == IlcaNetSessionNetworkType.Local)
			{
				GameStateChangeSet(GameState.GS_BrowseSession);
				return;
			}
			if (netSetting.networkType != IlcaNetSessionNetworkType.Internet && netSetting.networkType != IlcaNetSessionNetworkType.Lan)
				return;

			if (netSetting.matchingMode == IlcaNetSessionInitMode.MatchingWait)
			{
				GameStateChangeSet(GameState.GS_BrowseSession);
				return;
			}
			CreateSessionSet(null);
			SearchSessionSet();
			joinRandomSessionSetting.createSessionSetting = createSessionSetting;
			joinRandomSessionSetting.sessionSearchCriteriaList = sessionSearchCriteriaList;
			result = PiaPlugin.RegisterJoinRandomSessionSetting(joinRandomSessionSetting);
			result = PiaPlugin.ChangeStateAsync(PiaPlugin.State.SessionJoined);
			if (result.IsFailure())
			{
				HandleError(result);
				return;
			}
			GameStateChangeSet(GameState.GS_AsyncWait, PiaPlugin.AsyncProcessId.ChangeState, GameState.GS_JoinProcessRandom);
		}
		private static void CreateSessionSet(string password) {
			PiaPlugin.Result result = default;
			createSessionSetting.SetGameMode(netSetting.gameMode);
			createSessionSetting.SetParticipantNumMax(netSetting.playerNumMax);
			createSessionSetting.SetOpenSession(netSetting.bOpenSession);
			createSessionSetting.SetApplicationData(netSetting.applicationData);
			createSessionSetting.SetWirelessCryptoKey(netSetting.wirelessCryptoKey);
			createSessionSetting.SetLocalCommunicationId(netSetting.localCommunicationId);
			if (password != null)
			{
				result = createSessionSetting.SetSessionUserPassword(password);
