			}
			if (netSetting.matchmakeKeyword != null)
			{
				result = createSessionSetting.SetSessionMatchmakeKeyword(netSetting.matchmakeKeyword);
				result.IsFailure();
			}
			else if (netSetting.attributeValueEnable)
			{
				for (int i = 0; i < IlcaNetSessionSetting.attributeMax; i++)
				{
					createAttribute[i].index = (uint)i;
					createAttribute[i].value = netSetting.createSessionAttributeValue[i];
				}
				createSessionSetting.SetAttributeList(createAttributeList);
			}
		}
		private static void SearchSessionSet() {
			PiaPlugin.Result result = default;
			sessionSearchCriteriaList[0].SetGameMode(netSetting.gameMode);
			if (netSetting.networkType != IlcaNetSessionNetworkType.Local || !netSetting.playerNumFreeSearchLocalOnly)
				sessionSearchCriteriaList[0].SetParticipantNumMax(netSetting.playerNumMax);

			sessionSearchCriteriaList[0].SetOpenedOnly(netSetting.bSetOpenedOnly);
			sessionSearchCriteriaList[0].SetVacantOnly(netSetting.bSetVacantOnly);
			if (netSetting.networkType != IlcaNetSessionNetworkType.Local)
				sessionSearchCriteriaList[0].resultRange[0] = uint.MaxValue;
			else
				sessionSearchCriteriaList[0].resultRange[0] = 0;

			sessionSearchCriteriaList[0].resultRange[1] = netSetting.searchSessionPropertyMax;
			sessionSearchCriteriaList[0].SetLocalCommunicationId(netSetting.localCommunicationId);
			sessionSearchCriteriaList[0].SetExcludeUserPasswordSet(netSetting.bExcludeUserPassword);
			if (netSetting.matchmakeKeyword != null)
			{
				result = sessionSearchCriteriaList[0].SetSessionMatchmakeKeyword(netSetting.matchmakeKeyword);
				result.IsFailure();
			}
			else if (netSetting.attributeValueEnable)
			{
				for (int i = 0; i < IlcaNetSessionSetting.attributeMax; i++)
				{
					searchAttributeRange[i].min = netSetting.searchSessionAttributeValueMin[i];
					searchAttributeRange[i].max = netSetting.searchSessionAttributeValueMax[i];
				}
				sessionSearchCriteriaList[0].SetAttributeRangeList(searchAttributeRangeList);
			}
		}
