		private static void GameState_BrowseSessionAfter_InternetRandomAikotoba() {
			getproListAikotoba.Clear();
			uint size = PiaPluginSession.GetBrowsedSessionPropertyListSize();
			if (size == 0)
			{
				SessionCreateAsyncCore(null, GameState.GS_JoinProcess);
				return;
			}
			for (uint i = 0; i != size; i++)
				getproListAikotoba.Add(PiaPluginSession.GetBrowsedSessionProperty(i));

			getproListAikotoba.Shuffle();
			if (getproListAikotoba.Count < 1)
				return;

			for (int i = 0; i < getproListAikotoba.Count; i++)
			{
				if (getproListAikotoba[i].isOpened && getproListAikotoba[i].participantNumMax > getproListAikotoba[i].currentParticipantNum)
				{
					// shipped: joins by the index in the SHUFFLED list
					SessionJoinAsyncCore((uint)i, null, 0, GameState.GS_JoinProcess);
					return;
				}
			}
			SessionCreateAsyncCore(null, GameState.GS_JoinProcess);
		}
		private static int getproListCompIDIndex(global::INL1.IlcaNetSession.getProListMod a, global::INL1.IlcaNetSession.getProListMod b) {
			return (int)(b.pro.sessionId - a.pro.sessionId);
		}
		private static int getproListCompPlayerNumIndex(global::INL1.IlcaNetSession.getProListMod a, global::INL1.IlcaNetSession.getProListMod b) {
			return b.pro.currentParticipantNum - a.pro.currentParticipantNum;
		}
		private static void GameState_BrowseSessionAfter_LocalRandom2() {
			byte[] myAppData = null;
			byte[] proAppData = null;
			if (localRandomSessionList_counter == 0)
			{
				getproListIndex.Clear();
				uint size = PiaPluginSession.GetBrowsedSessionPropertyListSize();
				for (uint i = 0; i != size; i++)
				{
					getProListMod mod = new getProListMod();
					mod.id = i;
					mod.pro = PiaPluginSession.GetBrowsedSessionProperty(i);
					getproListIndex.Add(mod);
				}
				getproListIndex.Sort(getproListCompIDIndex);
				getproListIndex.Sort(getproListCompPlayerNumIndex);
			}
			if (getproListIndex.Count < 1)
			{
				localRandomSessionList_counter = 0;
				SessionCreateAsyncCore(netSetting.matchmakeKeyword, GameState.GS_JoinProcess_LocalRandom);
				return;
			}
			while (getproListIndex.Count > localRandomSessionList_counter)
			{
				if (getproListIndex[(int)localRandomSessionList_counter].pro.isOpened &&
					getproListIndex[(int)localRandomSessionList_counter].pro.participantNumMax > getproListIndex[(int)localRandomSessionList_counter].pro.currentParticipantNum)
				{
					if (getproListIndex[(int)localRandomSessionList_counter].pro.isRestrictedByUserPassword)
					{
						if (netSetting.matchmakeKeyword != null)
						{
							int myAppDataSize = netSetting.applicationData.Length;
							uint proAppDataSize = getproListIndex[(int)localRandomSessionList_counter].pro.applicationDataSize;
							myAppData = netSetting.applicationData;
							proAppData = getproListIndex[(int)localRandomSessionList_counter].pro.applicationData;
							bool join;
							if (myAppDataSize >= OverPasswordMinSize && proAppDataSize >= OverPasswordMinSize)
							{
								if (!OverPasswordMagicNumberIDCheck(ref myAppData, 0) || !OverPasswordMagicNumberIDCheck(ref proAppData, 0))
								{
									join = true;
								}
								else
								{
									uint overSize = OverPasswordSizeGet(ref myAppData, 0);
									join = overSize == OverPasswordSizeGet(ref proAppData, 0) && OverPasswordCompare(ref myAppData, 0, ref proAppData, 0, overSize);
								}
							}
							else if (myAppDataSize >= OverPasswordMinSize && OverPasswordMagicNumberIDCheck(ref myAppData, 0))
							{
								join = false;
							}
							else if (proAppDataSize >= OverPasswordMinSize && OverPasswordMagicNumberIDCheck(ref proAppData, 0))
							{
								join = false;
							}
							else
							{
								join = true;
							}
							if (join)
							{
								SessionJoinAsyncCore(getproListIndex[(int)localRandomSessionList_counter].id, netSetting.matchmakeKeyword, 0, GameState.GS_JoinProcess_LocalRandom);
								localRandomSessionList_counter++;
								return;
							}
						}
					}
					else if (netSetting.matchmakeKeyword == null)
					{
						SessionJoinAsyncCore(getproListIndex[(int)localRandomSessionList_counter].id, null, 0, GameState.GS_JoinProcess_LocalRandom);
						localRandomSessionList_counter++;
						return;
					}
				}
				localRandomSessionList_counter++;
			}
			localRandomSessionList_counter = 0;
			SessionCreateAsyncCore(netSetting.matchmakeKeyword, GameState.GS_JoinProcess_LocalRandom);
		}
		private static bool OverPasswordMagicNumberIDCheck(ref byte[] c, int i) {
			return c[i] == 'I' && c[i + 1] == 'N' && c[i + 2] == 'L' && c[i + 3] == '1' && c[i + OverPasswordIDposition] == 0xfe;
		}
		private static uint OverPasswordSizeGet(ref byte[] c, int i) {
			return c[i + OverPasswordSizePosition];
		}
		private static bool OverPasswordCompare(ref byte[] c1, int i, ref byte[] c2, int j, uint size) {
			int k;
			for (k = 0; k < size; k++)
			{
				if (c1[i + OverPasswordDataPosition + k] != c2[j + OverPasswordDataPosition + k])
					break;
			}
			return k == size;
		}
		private static void ToGameFrontBeforeLocalRandom() {
			localSessionRandomValue = userRandomNumLocalFunc();
			gameFront_r_no[0] = 0;
			gameFront_cnt[0] = 0;
			GameStateChangeSet(GameState.GS_GameFrontBefore_LocalRandom);
		}
		private static void ToGameFront() {
			localSessionRandomValue = userRandomNumLocalFunc();
			if (netSetting.gamingStartMode != IlcaNetSessionGamingStartMode.Natural)
			{
				GameFrontRnoInit();
				GameStateChangeSet(GameState.GS_GameFront);
				return;
			}
			ToGameInit();
		}
		private static void ToGameInit() {
			if (IsHost())
			{
				SessonOpenCloseInit();
				netSessionOpenCloseStatus = (IlcaNetSessionOpenStatus)PiaPluginSession.GetSessionOpenStatus();
			}
			GameStateChangeSet(GameState.GS_Game);
		}
		private static void autoRetryRandomMatchmakeCounterReset() {
			autoRetryRandomMatchmakeCounter = 0;
		}
		private static bool AutoRetryCheck(global::PiaPlugin.Result result) {
			if (PiaPlugin.ConvertHandlingTypeToState(result.handlingType) < PiaPlugin.State.LoggedIn)
				return false;

			if (autoRetryRandomMatchmakeCounter < netSetting.autoRetryRandomMatchmakeMaxNum)
			{
				if ((InternetRandomMatchCheck() && result.viewerType == PiaPlugin.ViewerType.ShouldNotUse) || LanRandomMatchCheck())
				{
					autoRetryRandomMatchmakeCounter++;
					return true;
				}
			}
			if (autoRetryRandomMatchmakeCounter < netSetting.autoRetryRandomMatchmakeMaxNum + netSetting.autoRetryRandomMatchmakeMaxNumAddLocal && LocalRandomMatchCheck())
			{
				autoRetryRandomMatchmakeCounter++;
				return true;
			}
			switch (netSetting.autoRetryMode)
			{
				case IlcaNetSessionAutoRetryMode.Off:
					return false;
				case IlcaNetSessionAutoRetryMode.RetryNoViewer:
					return result.viewerType == PiaPlugin.ViewerType.ShouldNotUse;
				case IlcaNetSessionAutoRetryMode.RetryWithoutInternetNoView:
					if (netSetting.networkType == IlcaNetSessionNetworkType.Internet)
						return result.viewerType == PiaPlugin.ViewerType.ShouldNotUse;
					return true;
				default:
					return true;
			}
		}
		private static void GameState_JoinProcessAll() {
			PiaPlugin.Result result = PiaPlugin.ProgrammingErrorResult;
			PiaPlugin.AsyncState asyncState = default;
			PiaPlugin.AsyncProcessId asyncProcessId = PiaPlugin.GetAsyncProcessId();
			if (asyncProcessId != PiaPlugin.AsyncProcessId.ChangeState && asyncProcessId != PiaPlugin.AsyncProcessId.CreateSession &&
				asyncProcessId != PiaPlugin.AsyncProcessId.JoinSession)
			{
				DangerousEmergencyCall();
				return;
			}
			asyncState = PiaPlugin.GetAsyncProcessState(asyncProcessId);
			if (asyncState.isCompleted)
				result = asyncState.result;

			if (result.IsSuccess())
			{
				if (LocalRandomMatchCheck())
					ToGameFrontBeforeLocalRandom();
				else
					ToGameFront();
				return;
			}
			if (!AutoRetryCheck(result))
			{
				HandleError(result);
				return;
			}
			switch (result.resultValue)
			{
				case PiaPlugin.ResultValue.ResultStationConnectionFailed:
				case PiaPlugin.ResultValue.ResultJoinRequestDenied:
				case PiaPlugin.ResultValue.ResultTimeout:
				case PiaPlugin.ResultValue.ResultLocalCommunicationInvalidState:
				case PiaPlugin.ResultValue.ResultSessionIsNotFound:
				case PiaPlugin.ResultValue.ResultSessionIsClosed:
					SystemCallBackInit();
					CleanupRecoveryToLoggedIn();
					break;
				case PiaPlugin.ResultValue.ResultMatchmakeSessionIsFull:
				case PiaPlugin.ResultValue.ResultSessionUserPasswordUnmatch:
				case PiaPlugin.ResultValue.ResultSessionSystemPasswordUnmatch:
				case PiaPlugin.ResultValue.ResultHostIsNotFriend:
				case PiaPlugin.ResultValue.ResultSessionWrongState:
					if (LocalRandomMatchCheck())
					{
						SystemCallBackInit();
						isSystemCallBackReady = true;
						autoRetryRandomMatchmakeCounterReset();
						GameStateChangeSet(GameState.GS_BrowseSessionAfter_LocalRandom);
					}
					else
					{
						SystemCallBackInit();
						CleanupRecoveryToLoggedIn();
					}
					break;
				default:
					HandleError(result);
					break;
			}
		}
		private static bool InternetRandomMatchCheck() {
			if (netSetting.networkType != IlcaNetSessionNetworkType.Internet)
				return false;

			return netSetting.matchingMode == IlcaNetSessionInitMode.Random;
		}
		private static bool InternetRandomAikotobaMatchCheck() {
			if (netSetting.networkType != IlcaNetSessionNetworkType.Internet)
				return false;

			if (netSetting.matchingMode != IlcaNetSessionInitMode.Random)
				return false;

			if (netSetting.matchmakeKeyword == null)
				return false;

			return netSetting.matchmakeKeyword.Length > 0;
		}
		private static bool LocalRandomMatchCheck() {
			if (netSetting.networkType != IlcaNetSessionNetworkType.Local)
				return false;

			return netSetting.matchingMode == IlcaNetSessionInitMode.Random;
		}
		private static bool LanRandomMatchCheck() {
			if (netSetting.networkType != IlcaNetSessionNetworkType.Lan)
				return false;

			return netSetting.matchingMode == IlcaNetSessionInitMode.Random;
		}
		private static void GameState_GameFrontBefore_LocalRandom() {
			int num = NumStation();
			if (num != 1)
			{
				if (num < 2)
					return;

				GameFrontRnoInit();
				ToGameFront();
				return;
			}
			gameFront_cnt[1]++;
			if (gameFront_cnt[0]++ <= (netSetting.localRandomMatchmakeHostWaitTimeMask & localSessionRandomValue) + netSetting.localRandomMatchmakeHostWaitTime)
				return;

			if (gameFront_cnt[1] > netSetting.localRandomMatchmakeTimeUp)
			{
				GameFrontRnoInit();
				ToGameFront();
				return;
			}
			if (sessionEventCallbackFuncDelayMode != IlcaNetSessionCallbackMode.Smart)
				SystemCallBackInit();
			else
				SystemCallBackFinal();

			if (!CleanupRecoveryToLoggedIn())
				return;

			IlcaNetServer.MainThreadDispatchControl(false);
			GameStateChangeSet(GameState.GS_LoggedInReturnWaitWorker);
			UpdateDispatchWorkerSet(PiaPlugin.AsyncProcessId.ChangeState, false);
		}
		private static void GameState_GameFront() {
			switch (netSetting.gamingStartMode)
			{
				case IlcaNetSessionGamingStartMode.Two:
					if (NumStation() >= 2)
						ToGameInit();
					break;
				case IlcaNetSessionGamingStartMode.Max:
					if (NumStation() >= netSetting.playerNumMax)
						ToGameInit();
					break;
				default:
					ToGameInit();
					break;
			}
		}
		private static void GameState_Game() {
			if (netGameState_Game_AsyncWait == GameAsync.NoWork && IsHost() && IsAllNetworkAsyncCompleted())
			{
				int num = NumStation();
				if (num < netSetting.playerNumMax)
				{
					if (num >= 1 && num < netSetting.playerNumMax && netSessionOpenCloseStatus == IlcaNetSessionOpenStatus.Closed && netSetting.bAutoSessionOpen)
						SessionOpenHostAsync(null);
				}
				else if (netSessionOpenCloseStatus == IlcaNetSessionOpenStatus.Opened && netSetting.bAutoSessionClose)
				{
					SessionCloseHostAsync(null);
				}
			}
			if (netGameState_Game_AsyncWait == GameAsync.SessionOpenWait || netGameState_Game_AsyncWait == GameAsync.SessionCloseWait)
			{
				isCompletedSessionOpenCloseStatus = CheckSessionOpenCloseStatus();
				if (isCompletedSessionOpenCloseStatus)
				{
					netGameState_Game_AsyncWait = GameAsync.NoWork;
					if (openCloseCallback != null)
						openCloseCallback(netSessionOpenCloseStatus);
				}
			}
		}
		private static bool CheckSessionOpenCloseStatus() {
			switch (netSessionOpenCloseStatus)
			{
				case IlcaNetSessionOpenStatus.Opened:
					if (PiaPlugin.GetAsyncProcessState(PiaPlugin.AsyncProcessId.CloseSession).isCompleted)
					{
						SessonOpenCloseInit();
						netSessionOpenCloseStatus = IlcaNetSessionOpenStatus.Closed;
						return true;
					}
					break;
				case IlcaNetSessionOpenStatus.Closed:
					if (PiaPlugin.GetAsyncProcessState(PiaPlugin.AsyncProcessId.OpenSession).isCompleted)
					{
						SessonOpenCloseInit();
						netSessionOpenCloseStatus = IlcaNetSessionOpenStatus.Opened;
						return true;
					}
					break;
			}
			return false;
		}
		private static void GameState_LogoutCore() {
			PiaPlugin.Result result = default;
			result = PiaPlugin.ChangeStateAsync(PiaPlugin.State.LoggedOut);
			if (result.IsFailure())
			{
				result.Trace();
				return;
			}
			isLogoutFinalizeAsyncMoving = true;
			if (isNamerakaMode)
			{
				IlcaNetServer.MainThreadDispatchControl(false);
				GameStateChangeSet(GameState.GS_LogoutWaitWorker);
				UpdateDispatchWorkerSet(PiaPlugin.AsyncProcessId.ChangeState, false);
			}
			else
			{
				GameStateChangeSet(GameState.GS_AsyncWait, PiaPlugin.AsyncProcessId.ChangeState, GameState.GS_PiaFrameworkFinalize);
			}
		}
		private static void GameState_LogoutWaitWorker() {
			if (!isMainThreadDispatchActive)
				return;

			GameStateChangeSet(GameState.GS_PiaFrameworkFinalize);
			GameState_PiaFrameworkFinalize();
		}
		private static void GameState_PiaFrameworkFinalize() {
			isLogoutFinalizeAsyncMoving = false;
			if (netSetting.networkType == IlcaNetSessionNetworkType.Internet)
				IlcaNetServer.Final();

			if (isNamerakaMode)
			{
				IlcaNetServer.MainThreadDispatchControl(false);
				System.Threading.Thread thread = new System.Threading.Thread(new System.Threading.ThreadStart(GameState_PiaFrameworkFinalizeWorkerTh));
				thread.IsBackground = true;
				thread.Priority = System.Threading.ThreadPriority.BelowNormal;
				thread.Start();
				GameStateChangeSet(GameState.GS_PiaFrameworkFinalizeAfter);
			}
			else
			{
				PiaPlugin.FinalizeNetwork();
				PiaPlugin.FinalizeAll();
				GameStateChangeSet(GameState.GS_PiaFrameworkFinalizeAfter);
				GameState_PiaFrameworkFinalizeCoreAfter();
			}
		}
		private static void GameState_PiaFrameworkFinalizeWorkerTh() {
			PiaPlugin.FinalizeNetwork();
			PiaPlugin.FinalizeAll();
			IlcaNetServer.MainThreadDispatchControl(true);
		}
		private static void GameState_PiaFrameworkFinalizeCoreAfter() {
			if (!isMainThreadDispatchActive)
				return;

			IlcaNetSessionFinalCallback finalCallback = finalRequestCallbackfunc;
			bool crash = isCrash;
			CleanUpCore();
			if (crash)
			{
				GameStateChangeSet(GameState.GS_Crash);
				SessionStateSet(IlcaNetSessionState.SS_Crash);
			}
			else
			{
				GameStateChangeSet(GameState.GS_Final);
				SessionStateSet(IlcaNetSessionState.SS_Final);
			}
			if (finalCallback != null)
				finalCallback();
		}
		private static void GameState_ErrorHandling(bool direct = false) {
			PiaPlugin.AsyncState asyncState = default;
			PiaPlugin.Result result = default;
			bool dispCancel = isErrorViewerDispCancel;
			if (direct)
			{
				if (!isLogoutFinalizeAsyncMoving && PiaPlugin.GetJoinProcessState() > PiaPlugin.State.NetworkStartedUp)
					GameState_ErrorHandlingCoreToError();
				else
					GameState_ErrorHandlingCoreToCrash();
			}
			else
			{
				asyncState = PiaPlugin.GetAsyncProcessState(PiaPlugin.AsyncProcessId.HandleError);
				if (!asyncState.isCompleted || isLogoutFinalizeAsyncMoving)
				{
					GameState_ErrorHandlingCoreToCrash();
				}
				else
				{
					result = asyncState.result;
					if (result.IsFailure() || PiaPlugin.GetJoinProcessState() <= PiaPlugin.State.NetworkStartedUp)
						GameState_ErrorHandlingCoreToCrash();
					else
						GameState_ErrorHandlingCoreToError();
				}
			}
			isErrorHandleMoving = false;
			LastErrorViewerAppletSet(false);
			if (!dispCancel)
				GameState_ErrorHandlingCoreViewer(lastErrorResult);
		}
		private static void GameState_ErrorHandlingCoreToCrash() {
			isCrash = true;
			GameStateChangeSet(GameState.GS_PiaFrameworkFinalize);
		}
		private static void GameState_ErrorHandlingCoreToError() {
			GameStateChangeSet(GameState.GS_GameError);
		}
		private static void GameState_ErrorHandlingCoreViewer(global::PiaPlugin.Result res) {
			if (res.viewerType != PiaPlugin.ViewerType.ShouldUse && res.viewerType != PiaPlugin.ViewerType.MayUse)
				return;

			if (isErrorViewerDispNow)
				return;

			LastErrorViewerAppletSet(true);
			ErrorViewer(res);
		}
		private static void HandleError(global::PiaPlugin.Result errorResult) {
			errorResult.Trace();
			PiaPlugin.Assert(errorResult.IsFailure());
			if (errorResult.handlingType == PiaPlugin.HandlingType.ProgrammingError)
			{
				PiaPlugin.Assert(false);
				return;
			}
			if (SessionFinalizeProcessMovingCheck())
				return;

			if (isErrorHandleMoving)
				return;

			if (errorResult.handlingType < PiaPlugin.HandlingType.Cleanup)
				return;

			isErrorHandleMoving = true;
			lastErrorResult = errorResult;
			if (isSessionLeaveRequest)
				isSessionLeaveRequest = false;

			SystemCallBackFinal();
			errorHandleNextSessionState = PiaPlugin.ConvertHandlingTypeToState(lastErrorResult.handlingType);
			isErrorHandleNexInitialize = false;
			if (errorHandleNextSessionState < PiaPlugin.State.LoggedIn || netSetting.bSSCrashMode)
			{
				if (netSetting.networkType == IlcaNetSessionNetworkType.Internet)
					isErrorHandleNexInitialize = true;

				isLogoutFinalizeAsyncMoving = true;
			}
			if (IsAllNetworkAsyncCompleted() && !IlcaNetServer.IsRunning())
				HandleErrorCore();
			else
				GameStateChangeSet(GameState.GS_HandleErrorWait);
		}
		private static void HandleErrorCore() {
			PiaPlugin.Result result = default;
			if (isErrorHandleNexInitialize)
			{
				IlcaNetServer.Final();
				isErrorHandleNexInitialize = false;
			}
			if (PiaPlugin.GetJoinProcessState() > errorHandleNextSessionState)
			{
				GeneraNexTerminateImmediatelySet();
				result = PiaPlugin.HandleErrorAsync(lastErrorResult);
				if (result.IsFailure())
				{
					result.Trace();
					PiaPlugin.Assert(false);
					return;
				}
				if (isNamerakaMode)
				{
					IlcaNetServer.MainThreadDispatchControl(false);
					GameStateChangeSet(GameState.GS_HandleErrorWaitWorker);
					UpdateDispatchWorkerSet(PiaPlugin.AsyncProcessId.HandleError, false);
				}
				else
				{
					GameStateChangeSet(GameState.GS_AsyncWait, PiaPlugin.AsyncProcessId.HandleError, GameState.GS_ErrorHandling);
				}
			}
			else
			{
				GameStateChangeSet(GameState.GS_ErrorHandling);
				GameState_ErrorHandling(true);
			}
		}
		private static void GameState_HandleErrorWaitWorker() {
			if (!isMainThreadDispatchActive)
				return;

			GameStateChangeSet(GameState.GS_ErrorHandling);
			GameState_ErrorHandling(false);
		}
		private static void GameState_HandleErrorWait() {
			if (!IsAllNetworkAsyncCompleted())
				return;

			if (IlcaNetServer.IsRunning())
				return;

			HandleErrorCore();
		}
		private static global::PiaPlugin.State MyConvertHandlingTypeToStat(global::PiaPlugin.HandlingType handle) {
			PiaPlugin.State state = PiaPlugin.GetJoinProcessState();
			switch (handle)
			{
				case PiaPlugin.HandlingType.Cleanup:
				case PiaPlugin.HandlingType.CleanupWithLeave:
					if (state >= PiaPlugin.State.SessionCleanedUp)
						state = PiaPlugin.State.SessionCleanedUp;
					break;
				case PiaPlugin.HandlingType.LogoutWithLeave:
				case PiaPlugin.HandlingType.ShutdownNetwork:
					if (state >= PiaPlugin.State.LoggedOut)
						state = PiaPlugin.State.LoggedOut;
					break;
				case PiaPlugin.HandlingType.Finalize:
					if (state >= PiaPlugin.State.NetworkCleanedUp)
						state = PiaPlugin.State.NetworkCleanedUp;
					break;
			}
			return state;
		}
